inline constexpr Asset ASSETS[] = {
  {"/index.html", "text/html; charset=utf-8", INDEX_HTML_GZ, sizeof(INDEX_HTML_GZ)},
  {"/assets/app.js", "text/javascript; charset=utf-8", APP_JS_GZ, sizeof(APP_JS_GZ)},
  {"/assets/style.css", "text/css; charset=utf-8", STYLE_CSS_GZ, sizeof(STYLE_CSS_GZ)}
};

inline const Asset* findAsset(const char* path) {
  for (const auto& asset : ASSETS) {
    if (std::strcmp(asset.path, path) == 0) return &asset;
  }
  return nullptr;
}
